enum class BodyPart : u8 { none, legs, torso, head };
namespace person_hit { constexpr f32 kHipZ = 0.92, kHeadUp = 0.73, kHeadR = 0.155; }
namespace person_hit { inline f32 lean(f32 speed) { return std::clamp(speed - 2.5, 0.0, 5.0) * 0.035; } }
namespace person_hit { inline bool box_entry(Vec3 from, Vec3 seg, Vec3 c, Vec3 ax, Vec3 ay, Vec3 az, Vec3 h, f32& t_out) {
  const Vec3 o = from - c;
  const f32 po[3] = {converted::wide::dot(o, ax), converted::wide::dot(o, ay), converted::wide::dot(o, az)}, pd[3] = {converted::wide::dot(seg, ax), converted::wide::dot(seg, ay), converted::wide::dot(seg, az)};
  const f32 hh[3] = {h.x, h.y, h.z};
  f32 t0 = 0, t1 = 1;
  for (int a = 0; a < 3; ++a) {
    if (std::fabs(converted::at(pd, a)) < 1e-7) { if (std::fabs(converted::at(po, a)) > converted::at(hh, a)) return false; continue; }
    f32 ta = (-converted::at(hh, a) - converted::at(po, a)) / converted::at(pd, a), tb = (converted::at(hh, a) - converted::at(po, a)) / converted::at(pd, a);
    if (ta > tb) std::swap(ta, tb);
    t0 = std::fmax(t0, ta);
    t1 = std::fmin(t1, tb);
    if (t0 > t1) return false;
  }
  t_out = t0;
  return true;
} }
namespace person_hit { inline bool sphere_entry(Vec3 from, Vec3 seg, Vec3 c, f32 r, f32& t_out) {
  const Vec3 o = from - c;
  const f32 a = converted::wide::dot(seg, seg), b = converted::wide::dot(o, seg), cc = converted::wide::dot(o, o) - r * r;
  if (a < 1e-9) return false;
  if (cc <= 0) { t_out = 0; return true; }
  const f32 disc = b * b - a * cc;
  if (disc < 0 || b > 0) return false;
  const f32 t = (-b - kern::math::sqrt(disc)) / a;
  if (t > 1) return false;
  t_out = std::fmax(0.0, t);
  return true;
} }
namespace person_hit { inline BodyPart hit(Vec3 feet, f32 yaw, f32 speed, Vec3 from, Vec3 seg, f32& t_out, f32 pad = 1.0, f32 scale = 1.0) {
  const f32 cy = kern::math::cos(yaw), sy = kern::math::sin(yaw), l = lean(speed), cl = kern::math::cos(l), sl = kern::math::sin(l);
  const Vec3 fx{cy, sy, 0}, fy{-sy, cy, 0}, up{0, 0, 1};
  // the leaning body frame: up tilts forward
  const Vec3 bz = up * cl + fx * sl, bx = fx * cl - up * sl;
  const Vec3 hip = feet + up * (kHipZ * scale);
  BodyPart best = BodyPart::none;
  f32 bt = 2, t;
  if (sphere_entry(from, seg, hip + bz * (kHeadUp * scale), kHeadR * pad * scale, t) && t < bt) { bt = t; best = BodyPart::head; }
  // torso 0.24 x 0.42 x 0.6 from the hip up, with the arms beside it (to 0.33 either side)
  if (box_entry(from, seg, hip + bz * (0.29 * scale), bx, fy, bz, Vec3{0.15, 0.31, 0.31} * (pad * scale), t) && t < bt - 1e-5) { bt = t; best = BodyPart::torso; }
  // the legs, hip to shoe
  if (box_entry(from, seg, feet + up * (0.47 * scale), fx, fy, up, Vec3{0.15, 0.2, 0.47} * (pad * scale), t) && t < bt - 1e-5) { bt = t; best = BodyPart::legs; }
  t_out = bt;
  return best;
} }
constexpr f32 kPavement = 1.6;
constexpr f32 kWitness = 45;
constexpr f32 kCapsuleR = 0.32;
const Vec3 kShirts[] = {{0.62, 0.12, 0.1}, {0.16, 0.28, 0.55}, {0.85, 0.82, 0.74}, {0.2, 0.42, 0.25}, {0.9, 0.62, 0.15},
                        {0.35, 0.35, 0.38}, {0.55, 0.3, 0.55}, {0.1, 0.1, 0.12}, {0.75, 0.45, 0.4}, {0.3, 0.6, 0.7}};
const Vec3 kPants[] = {{0.12, 0.14, 0.22}, {0.2, 0.2, 0.22}, {0.38, 0.3, 0.22}, {0.08, 0.08, 0.09}, {0.45, 0.45, 0.48}, {0.25, 0.3, 0.45}};
const Vec3 kSkins[] = {{0.94, 0.76, 0.62}, {0.78, 0.58, 0.43}, {0.66, 0.44, 0.32}, {0.48, 0.31, 0.22}, {0.86, 0.66, 0.5}};
f32 dist2d(Vec3 a, Vec3 b) { return hypot_bp(a.x - b.x, a.y - b.y); }
f32 approach_angle(f32 cur, f32 target, f32 max_step) { return cur + clampf(wrap_pi(target - cur), -max_step, max_step); }
bool inside_building(const World& w, Vec3 p, f32 ground) {
  // A roof above the ground here (the terrain itself answers at ground height).
  const RayResult h = cast(w, {p.x, p.y, ground + 60}, {0, 0, -1}, 70, {}, kCatWorld);
  return h.hit && h.point.z > ground + 0.35;
}
bool People::route_point(const Person& p, const std::vector<Lane>& lanes, Vec3& out, f32& heading) const {
  if (p.lane < 0 || p.lane >= static_cast<i32>(lanes.size())) return false;
  const Lane& L = converted::at(lanes, p.lane);
  if (!L.alive || p.seg < 0 || p.seg + 1 >= static_cast<i32>(L.points.size())) return false;
  const Vec2 a = converted::at(L.points, p.seg), b = converted::at(L.points, p.seg + 1);
  const Vec2 d = b - a;
  const f32 len = std::fmax(1e-3, hypot_bp(d.x, d.y));
  const Vec2 u = d * (1.0 / len), walk = u * static_cast<f32>(p.dir), right{walk.y, -walk.x};
  const Vec2 c = a + u * clampf(p.along, 0, len) + right * (p.side * p.off);
  out = {c.x, c.y, 0};
  heading = kern::math::atan2(walk.y, walk.x);
  return true;
}
bool People::free_move(const World& w, Person& p, Vec2 dir, f32 step, bool keep) {
  const f32 l = hypot_bp(dir.x, dir.y);
  if (l < 1e-5 || step <= 0) return true;
  dir = dir * (1.0 / l);
  for (f32 ang : {0.0, 0.5, -0.5, 1.0, -1.0, 1.6, -1.6}) {
    const f32 c = kern::math::cos(ang), s = kern::math::sin(ang);
    const Vec2 d{dir.x * c - dir.y * s, dir.x * s + dir.y * c};
    if (cast(w, p.pos + Vec3{0, 0, 1.0}, {d.x, d.y, 0}, step + kCapsuleR, {}, kCatWorld).hit) continue;
    p.pos.x += d.x * step;
    p.pos.y += d.y * step;
    if (keep && ang != 0) p.flee_dir = d;
    return true;
  }
  return false;
}
i32 People::add_officer(Vec3 at, f32 yaw, i32 unit, u32 seed) {
  Person p;
  p.kind = Kind::officer;
  p.state = State::officer;
  p.pos = at;
  p.yaw = yaw;
  p.hp = 100;  // police_ground_units.mjs COP_HP
  p.unit = unit;
  p.seed = seed;
  p.shirt = {0.14, 0.19, 0.31};
  p.pants = {0.1, 0.13, 0.19};
  p.skin = converted::at(kSkins, seed % 5);
  for (std::size_t i = 0; i < people_.size(); converted::pre_inc(i))
    if (converted::at(people_, i).state == State::gone) { converted::at(people_, i) = p; return static_cast<i32>(i); }
  people_.push_back(p);
  return static_cast<i32>(converted::minus(people_.size(), 1));
}
i32 People::add_citizen(Vec3 at, f32 yaw, u32 seed) {
  Person p;
  p.kind = Kind::citizen;
  p.state = State::walk;
  p.pos = at;
  p.yaw = yaw;
  p.seed = seed;
  p.speed = 1.0 + static_cast<f32>((seed >> 7) % 66) / 100;
  p.fitness = 0.75 + static_cast<f32>((seed >> 11) % 51) / 100;
  p.shirt = converted::at(kShirts, (seed >> 3) % 10);
  p.pants = converted::at(kPants, (seed >> 9) % 6);
  p.skin = converted::at(kSkins, (seed >> 13) % 5);
  for (std::size_t i = 0; i < people_.size(); converted::pre_inc(i))
    if (converted::at(people_, i).state == State::gone) { converted::at(people_, i) = p; return static_cast<i32>(i); }
  people_.push_back(p);
  return static_cast<i32>(converted::minus(people_.size(), 1));
}
i32 People::add_scripted(Kind k, Vec3 at, f32 yaw, f32 hp, u32 seed, Vec3 shirt, Vec3 pants, Vec3 skin, u8 role) {
  Person p;
  p.kind = k;
  p.state = State::officer;  // moved by its owner, not by walk()
  p.pos = at;
  p.yaw = yaw;
  p.hp = hp;
  p.seed = seed;
  p.shirt = shirt;
  p.pants = pants;
  p.skin = skin;
  p.role = role;
  for (std::size_t i = 0; i < people_.size(); converted::pre_inc(i))
    if (converted::at(people_, i).state == State::gone) { converted::at(people_, i) = p; return static_cast<i32>(i); }
  people_.push_back(p);
  return static_cast<i32>(converted::minus(people_.size(), 1));
}
u32 People::count(Kind k, bool alive_only) const {
  u32 n = 0;
  for (const Person& p : people_)
    if (p.kind == k && p.state != State::gone && (!alive_only || p.state != State::down)) ++n;
  return n;
}
bool People::witnessed(Vec3 at) const {
  for (const Person& p : people_)
    if (p.kind == Kind::citizen && (p.state == State::walk || p.state == State::wait || p.state == State::flee) && dist2d(p.pos, at) < kWitness) return true;
  return false;
}
f32 near_any(const PeopleView& v, Vec3 p) {
  f32 d = dist2d(p, v.focus);
  for (const Vec3& f : v.foci) d = std::fmin(d, dist2d(p, f));
  return d;
}
void People::dress(Person& p) {
  const u32 seed = p.seed;
  p.speed = 1.0 + static_cast<f32>((seed >> 7) % 66) / 100;
  p.fitness = 0.75 + static_cast<f32>((seed >> 11) % 51) / 100;
  p.shirt = converted::at(kShirts, (seed >> 3) % 10);
  p.pants = converted::at(kPants, (seed >> 9) % 6);
  p.skin = converted::at(kSkins, (seed >> 13) % 5);
}
void People::apply_snapshot(const std::vector<NetPerson>& list, f32 now) {
  std::vector<bool> seen(converted::count(people_.size()), false);
  for (const NetPerson& n : list) {
    i32 at = -1;
    for (std::size_t i = 0; i < people_.size(); converted::pre_inc(i))
      if (converted::at(people_, i).kind == Kind::citizen && converted::at(people_, i).net == n.idx && converted::at(people_, i).state != State::gone) { at = static_cast<i32>(i); break; }
    const bool host_down = n.state == static_cast<u8>(State::down);
    if (at < 0) {
      if (host_down) continue;  // a body we never saw walk: not worth showing
      Person p;
      p.kind = Kind::citizen;
      p.seed = n.seed;
      dress(p);
      p.net = n.idx;
      p.pos = p.net_to = n.pos;
      p.yaw = n.yaw;
      p.state = static_cast<State>(converted::among({0, 1, 2, 3, 4, 5, 6}, n.state <= static_cast<u8>(State::fight) ? n.state : 0));
      bool placed = false;
      for (std::size_t i = 0; i < people_.size(); converted::pre_inc(i))
        if (converted::at(people_, i).state == State::gone) { converted::at(people_, i) = p; at = static_cast<i32>(i); placed = true; break; }
      if (!placed) { people_.push_back(p); seen.push_back(false); at = static_cast<i32>(converted::minus(people_.size(), 1)); }
    }
    converted::at(seen, static_cast<std::size_t>(at)) = true;
    Person& p = converted::at(people_, static_cast<std::size_t>(at));
    if (p.seed != n.seed) { p.seed = n.seed; dress(p); p.pos = n.pos; }
    if (p.state == State::down) continue;
    if (host_down) { kill(at, Vec3{kern::math::cos(n.yaw), kern::math::sin(n.yaw), 0}, false, now, false); continue; }
    if ((n.flags & 1) && now >= p.knocked_until) { knock(at, Vec3{kern::math::cos(n.yaw), kern::math::sin(n.yaw), 0.5}, now); continue; }
    p.net_to = n.pos;
    p.net_at = n.at;
    p.v = n.v;
    if (now >= p.knocked_until) {
      p.state = static_cast<State>(converted::among({0, 1, 2, 3, 4, 5, 6}, n.state <= static_cast<u8>(State::fight) ? n.state : 0));
      // far off (a respawn of his, a teleport): there at once
      if (dist2d(p.pos, n.pos) > 6) p.pos = n.pos;
      p.yaw = n.yaw;
    }
  }
  for (std::size_t i = 0; i < seen.size() && i < people_.size(); converted::pre_inc(i)) {
    Person& p = converted::at(people_, i);
    if (converted::at(seen, i) || p.kind != Kind::citizen || p.net < 0) continue;
    if (p.state == State::down || now < p.knocked_until) continue;  // a body / a ragdoll stays its time
    p.state = State::gone;
  }
}
void People::frighten(Vec3 at, f32 radius, f32 now, f32 strength) {
  for (Person& p : people_) {
    if (p.kind != Kind::citizen || p.state == State::down || p.state == State::gone || p.state == State::fight) continue;
    const f32 d = dist2d(p.pos, at);
    if (d > radius) continue;
    // Close by everyone runs; further out about half do (pedestrian_agents.mjs frighten).
    const u32 roll_bits = (p.seed ^ static_cast<u32>(converted::fits<unsigned int>(now * 1000))) * 2246822519u;
    const f32 roll = static_cast<f32>(roll_bits >> 8) / 16777216.0;
    if (d > radius * 0.45 && roll < 0.5) continue;
    Vec2 away{p.pos.x - at.x, p.pos.y - at.y};
    const f32 l = hypot_bp(away.x, away.y);
    away = l > 0.3 ? away * (1.0 / l) : Vec2{kern::math::cos(roll * 6.28), kern::math::sin(roll * 6.28)};
    const f32 s = strength;
    p.flee_dir = away;
    p.flee_speed = clampf((3.4 + 1.5 * s) * p.fitness, 2.8, 7.2);
    p.flee_until = std::fmax(p.flee_until, now + 5.6 * (1.3 + 0.7 * roll));
    if (s >= 1) {
      p.burst_until = std::fmax(p.burst_until, now + 1.8 + 2.6 * std::fmin(1.6, s) * roll);
      if (roll < 0.55) p.hands_up_until = now + 0.9 + 1.8 * roll;
    }
    p.shaken_until = p.flee_until + 12 + 10 * roll;
    p.state = State::flee;
  }
}
void People::kill(i32 i, Vec3 from_dir, bool by_player, f32 now, bool hit_by_car) {
  Person& p = converted::at(people_, static_cast<std::size_t>(i));
  if (p.state == State::down || p.state == State::gone) return;
  const Vec3 at = p.pos;
  const bool officer = p.kind == Kind::officer;
  p.state = State::down;
  p.hp = 0;
  p.down_at = now;
  p.v = 0;
  const f32 l = hypot_bp(from_dir.x, from_dir.y);
  p.fall_dir = l > 1e-3 ? Vec3{from_dir.x / l, from_dir.y / l, 0} : Vec3{kern::math::cos(p.yaw), kern::math::sin(p.yaw), 0};
  deaths_.push_back({i, p.kind, by_player, last_head_});
  falls_.push_back({i, from_dir, hit_by_car, false});  // ragdoll (M3 life)
  // Soldiers and zombies are no crime (military_response.mjs, zombie_nights.mjs); a sandbox
  // enemy down counts as "police-kill" severity 1 (sandbox_game.mjs killEnemy).
  if (by_player && (p.kind == Kind::citizen || officer)) {
    const wanted::Crime c = officer ? wanted::Crime::police_officer : wanted::Crime::person;
    reports_.push_back({c, at, officer || witnessed(at)});
  } else if (by_player && p.kind == Kind::enemy) reports_.push_back({wanted::Crime::person_hit, at, true});
  (void)hit_by_car;
  frighten(at, 22, now, 1.2);
}
void People::mate_hurt(i32 index, u32 seed, f32 damage, HurtBy by, Vec3 push, f32 now) {
  if (index < 0 || index >= static_cast<i32>(people_.size()) || !(damage > 0)) return;
  Person& p = converted::at(people_, static_cast<std::size_t>(index));
  if (p.kind != Kind::citizen || p.seed != seed || p.state == State::down || p.state == State::gone || now < p.knocked_until) return;
  p.hp -= damage;
  p.hurt_at = now;
  if (p.hp <= 0) { kill(index, push, false, now, by == HurtBy::vehicle); return; }
  if (by == HurtBy::vehicle) {
    falls_.push_back({index, push, true, true});
    p.knocked_until = now + 6;
    p.v = 0;
    frighten(p.pos, 8, now, 1.4);
    return;
  }
  if (by == HurtBy::blow && p.hp > 35) p.v = 0;  // a blow he takes standing: a stagger
  else knock(index, push, now);
  frighten(p.pos, 3, now, 1.6);
}
i32 People::shot(Vec3 from, Vec3& to, f32 damage, bool by_player, f32 now, f32 melee_ns, f32 self_r) {
  i32 best = -1;
  f32 best_s = 2;
  bool head = false;
  Vec3 hit_point;
  for (std::size_t i = 0; i < people_.size(); converted::pre_inc(i)) {
    const Person& p = converted::at(people_, i);
    if (p.state == State::down || p.state == State::gone) continue;
    if (dist2d(p.pos, from) < self_r) continue;  // the shooter himself
    if (p.kind == Kind::citizen && now < p.knocked_until) continue;  // down as a ragdoll: the body is hidden
    // the body as it is drawn (person_hit.h): legs, the leaning torso with the arms, the head
    f32 s = 2;
    const BodyPart part = person_hit::hit(p.pos, p.yaw, p.v, from, to - from, s, 1.08);
    if (part != BodyPart::none && s < best_s) {
      best_s = s;
      best = static_cast<i32>(i);
      head = part == BodyPart::head;
      hit_point = from + (to - from) * s;
    }
  }
  last_head_ = false;
  if (best < 0) return -1;
  Person& p = converted::at(people_, static_cast<std::size_t>(best));
  to = hit_point;
  last_head_ = head;
  if (damage > 0 || melee_ns >= 0) p.hurt_at = now;
  if (by_player && p.kind == Kind::citizen) { p.provoked_at = now; p.provoked_hit = true; }
  const Vec3 dir = to - from;
  if (p.kind == Kind::citizen && damage > 0) {
    const f32 hd = std::fmax(1e-3, hypot_bp(dir.x, dir.y));
    const Vec3 flat{dir.x / hd, dir.y / hd, 0};
    const f32 hp_before = p.hp;
    if (melee_ns >= 0) {
      // world_procedural_population.mjs punch(): hp - damage; dead at 0, down at 35, else a stagger
      const f32 k = std::fmax(0.5, melee_ns / 30);
      p.hp -= damage;
      if (p.hp <= 0) kill(best, dir, by_player, now, false);
      else if (p.hp <= 35) knock(best, flat * (2 * k) + Vec3{0, 0, 0.9}, now);
      else { const f32 step = std::fmin(0.6, 0.22 * k); p.pos = p.pos + flat * step; p.v = 0; }
    } else {
      // gameplay_final_runtime_v2.mjs: weaponDamage 55 (default), sniper 200; headshots SMG 165,
      // Glock / sniper 999 (Kern's damage 13 / 26 / 95 tells the gun)
      const f32 dmg = head ? (damage >= 26 ? 999.0 : 165.0) : (damage >= 90 ? 200.0 : 55.0);
      p.hp -= dmg;
      if (p.hp <= 0) kill(best, dir, by_player, now, false);
      else knock(best, flat * 2.5 + Vec3{0, 0, 1.4}, now);
    }
    if (p.state != State::down) {
      if (by_player) reports_.push_back({wanted::Crime::person_hit, p.pos, true});
      frighten(p.pos, 3, now, 1.6);
      // the host's citizen (MP client): what we did to him goes to the host (take_hurts)
      if (by_player && puppets_ && p.net >= 0)
        hurts_.push_back({static_cast<u8>(p.net), p.seed, hp_before - p.hp, melee_ns >= 0 ? HurtBy::blow : HurtBy::round,
                          melee_ns >= 0 ? flat * (2 * std::fmax(0.5, melee_ns / 30)) + Vec3{0, 0, 0.9} : flat * 2.5 + Vec3{0, 0, 1.4}});
    }
    return best;
  }
  f32 dealt = damage * (head ? 3.0 : 1.0);  // VS zones: head x3
  if (p.kind == Kind::officer && damage > 0 && melee_ns < 0) {
    // police_ground_units.mjs registerPoliceHit: HIT_DAMAGE 25 per counted hit; the gun decides how
    // often a round counts (gameplay_final_runtime_v2.mjs): MP 1 (head 3, routeKill max 3), Glock and
    // sniper 6 (hitWeight; head 10)
    const f32 hits = damage >= 26 ? (head ? 10.0 : 6.0) : (head ? 3.0 : 1.0);
    dealt = 25 * hits;
  }
  // a mate's unit: the hit is his to apply (take_remote_hits), by the same rule
  if (p.remote) {
    if (by_player && dealt > 0) remote_hits_.push_back({best, dealt});
    return best;
  }
  p.hp -= dealt;
  if (p.hp <= 0) kill(best, dir, by_player, now, false);
  else {
    if (by_player && p.kind == Kind::citizen) reports_.push_back({wanted::Crime::person_hit, p.pos, true});
    if (p.kind == Kind::citizen) frighten(p.pos, 3, now, 1.6);
  }
  return best;
}
void People::blast(Vec3 at, f32 radius, f32 damage, bool by_player, f32 now) {
  for (std::size_t i = 0; i < people_.size(); converted::pre_inc(i)) {
    Person& p = converted::at(people_, i);
    if (p.state == State::down || p.state == State::gone || p.remote) continue;  // (a mate's unit: his machine runs the blast on it)
    const f32 d = converted::wide::length(p.pos + Vec3{0, 0, 0.9} - at);
    if (d >= radius) continue;
    const f32 t = clampf(1 - d / radius, 0, 1);
    if (p.kind == Kind::citizen) {
      // gameplay_final_runtime_v2.mjs dispatchExplosion: a person within the falloff > .22 takes one
      // hit (55): the first knocks down, the next kills; lying there it takes nothing
      if (t * t * (3 - 2 * t) <= 0.22 || now < p.knocked_until) continue;
      p.hp -= 55;
      if (p.hp <= 0) kill(static_cast<i32>(i), p.pos - at, by_player, now, false);
      else knock(static_cast<i32>(i), p.pos - at, now);
      continue;
    }
    if (p.kind == Kind::officer) {
      // police_ground_units.mjs onExplosion: an officer out of the car within r (2..60) takes
      // COP_HP (1 - d / r) 1.6 + 20, d across the ground
      const f32 r = clampf(radius, 2, 60), d2 = dist2d(p.pos, at);
      if (d2 < r) p.hp -= 100 * (1 - d2 / r) * 1.6 + 20;
    } else
      p.hp -= damage * t * t * (3 - 2 * t);
    if (p.hp <= 0) kill(static_cast<i32>(i), p.pos - at, by_player, now, false);
  }
  frighten(at, radius * 2.5, now, 1.6);
}
void People::walk(Person& p, f32 dt, f32 now, const PeopleView& view, const CityStream& city, Rng& rng) {
  const std::vector<Lane>& lanes = city.lanes();
  const World& w = *view.physics;
  if (p.state == State::flee) {
    if (now < p.flee_until) {
      const f32 top = now < p.burst_until ? std::fmax(p.flee_speed, std::fmin(8.5, 6.6 * p.fitness)) : p.flee_speed;
      p.v += clampf(top - p.v, -3 * dt, 4.2 * dt);
      if (!free_move(w, p, p.flee_dir, p.v * dt, true)) p.flee_dir = p.flee_dir * -1.0;
      p.yaw = approach_angle(p.yaw, kern::math::atan2(p.flee_dir.y, p.flee_dir.x), dt * 6);
      return;
    }
    // Calm again: back to the nearest pavement and walk on, still hurried for a while.
    f32 best = 30;
    for (std::size_t li = 0; li < lanes.size(); converted::pre_inc(li)) {
      const Lane& L = converted::at(lanes, li);
      if (!L.alive) continue;
      for (std::size_t k = 0; converted::plus(k, 1) < L.points.size(); converted::pre_inc(k)) {
        const Vec2 a = converted::at(L.points, k), b = converted::at(L.points, converted::plus(k, 1)), d = b - a;
        const f32 l2 = d.x * d.x + d.y * d.y;
        if (l2 < 1) continue;
        const f32 t = clampf(((p.pos.x - a.x) * d.x + (p.pos.y - a.y) * d.y) / l2, 0, 1);
        const Vec2 q = a + d * t;
        const f32 dd = hypot_bp(p.pos.x - q.x, p.pos.y - q.y);
        if (dd < best) {
          best = dd;
          p.lane = static_cast<i32>(li);
          p.seg = static_cast<i32>(k);
          p.along = t * kern::math::sqrt(l2);
          p.dir = rng.unit() < 0.5 ? 1 : -1;
          const f32 cross = d.x * (p.pos.y - a.y) - d.y * (p.pos.x - a.x);  // > 0: left of the lane
          const f32 right_of_lane = cross < 0 ? 1.0 : -1.0;
          p.side = right_of_lane * static_cast<f32>(p.dir);
          p.off = L.width * 0.5 + kPavement;
        }
      }
    }
    p.state = State::wait;
    p.wait_until = now + 0.8 + rng.unit() * 1.5;
    return;
  }
  if (p.state == State::wait) {
    p.v = std::fmax(0.0, p.v - 3 * dt);
    if (now >= p.wait_until) p.state = State::walk;
    return;
  }
  // Walking along the pavement: advance the route, then step towards its point.
  const f32 hurry = now < p.shaken_until ? 1.45 : 1.0;
  p.v += clampf(p.speed * hurry - p.v, -3 * dt, 1.5 * dt);
  if (p.lane < 0 || p.lane >= static_cast<i32>(lanes.size()) || !converted::at(lanes, p.lane).alive) { p.state = State::gone; return; }
  const Lane& L = converted::at(lanes, p.lane);
  const i32 n = static_cast<i32>(L.points.size());
  auto seg_len = [&](i32 k) { const Vec2 d = converted::at(L.points, k + 1) - converted::at(L.points, k); return hypot_bp(d.x, d.y); };
  Vec3 target;
  f32 heading;
  route_point(p, lanes, target, heading);
  const f32 behind = dist2d(target, p.pos);
  if (behind < 1.6) {  // on the route: walk it (catching up first when pushed off it)
    p.along += p.dir * p.v * dt;
    // Along the polyline: `along` counts from the segment's first point in the lane's own direction.
    while (p.dir > 0 && p.along > seg_len(p.seg)) {
      p.along -= seg_len(p.seg);
      if (++p.seg >= n - 1) break;
    }
    while (p.dir < 0 && p.along < 0) {
      if (--p.seg < 0) break;
      p.along += seg_len(p.seg);
    }
    if (p.seg < 0 || p.seg >= n - 1) {
      // End of the street: go on along a street that starts here, else turn round (and keep to
      // the same pavement: the side flips with the walking direction).
      const Vec2 end = p.seg < 0 ? converted::front(L.points) : converted::back(L.points);
      i32 next = -1, next_dir = 1;
      const u32 start = rng.next();
      for (std::size_t k = 0; k < lanes.size() && next < 0; converted::pre_inc(k)) {
        const std::size_t j = converted::rem((converted::plus(start, k)), lanes.size());
        if (static_cast<i32>(j) == p.lane || !converted::at(lanes, j).alive || converted::at(lanes, j).points.size() < 2) continue;
        const Vec2 a = converted::front(converted::at(lanes, j).points), z = converted::back(converted::at(lanes, j).points);
        if (hypot_bp(a.x - end.x, a.y - end.y) < 4) { next = static_cast<i32>(j); next_dir = 1; }
        else if (hypot_bp(z.x - end.x, z.y - end.y) < 4) { next = static_cast<i32>(j); next_dir = -1; }
      }
      if (next >= 0) {
        p.lane = next;
        p.dir = next_dir;
        const Lane& N = converted::at(lanes, next);
        p.seg = next_dir > 0 ? 0 : static_cast<i32>(N.points.size()) - 2;
        const Vec2 d = converted::at(N.points, p.seg + 1) - converted::at(N.points, p.seg);
        p.along = next_dir > 0 ? 0 : hypot_bp(d.x, d.y);
        p.off = N.width * 0.5 + kPavement;
      } else {
        p.dir = -p.dir;
        p.side = -p.side;
        p.seg = std::clamp(p.seg, 0, n - 2);
        p.along = p.dir > 0 ? 0 : seg_len(p.seg);
      }
      if (rng.unit() < 0.25) { p.state = State::wait; p.wait_until = now + 1 + rng.unit() * 2.5; }
    }
    route_point(p, lanes, target, heading);
  }
  const Vec2 to{target.x - p.pos.x, target.y - p.pos.y};
  const f32 dl = hypot_bp(to.x, to.y);
  if (dl > 0.02) {
    const f32 step = std::fmin(dl, p.v * dt * (behind < 1.6 ? 1.25 : 1.6));
    if (behind < 1.6) { p.pos.x += to.x / dl * step; p.pos.y += to.y / dl * step; }
    else free_move(w, p, {to.x / dl, to.y / dl}, step, false);
    p.yaw = approach_angle(p.yaw, kern::math::atan2(to.y, to.x), dt * 4.5);
  }
}
